(function() {
  'use strict';
  var isMobile = window.innerWidth <= 600;
  var patched = new Set();

  function whenReady(gd, fn, tries) {
    tries = tries || 0;
    if (gd && gd._fullData && gd._fullLayout) { fn(gd); return; }
    if (tries > 12) return;
    setTimeout(function(){ whenReady(gd, fn, tries+1); }, 300);
  }

  function sectionTitle(gd) {
    var panel = gd.closest ? (gd.closest('.panel') || gd.parentElement) : gd.parentElement;
    var cur = panel;
    while (cur && cur !== document.body) {
      var prev = cur.previousElementSibling;
      while (prev) {
        if (/^H[1-6]$/.test(prev.tagName)) return (prev.textContent || '').toUpperCase();
        var h = prev.querySelector && prev.querySelector('h1,h2,h3');
        if (h) return (h.textContent || '').toUpperCase();
        prev = prev.previousElementSibling;
      }
      cur = cur.parentElement;
    }
    return '';
  }

  /* 1. YEAR DECIMAL TICK FIX — any axis whose range is [2017..2027] and spans >=1yr */
  function fixYearTicks(gd) {
    try {
      var lay = gd._fullLayout || {};
      ['xaxis','xaxis2','xaxis3','yaxis','yaxis2'].forEach(function(k){
        var ax = lay[k]; if (!ax) return;
        var r = ax.range || [];
        if (r.length !== 2) return;
        var lo = +r[0], hi = +r[1];
        if (isNaN(lo) || isNaN(hi)) return;
        if (lo >= 2017 && hi <= 2030 && (hi - lo) >= 1) {
          var patch = {};
          patch[k + '.tickmode'] = 'linear';
          patch[k + '.dtick'] = 1;
          patch[k + '.tickformat'] = 'd';
          Plotly.relayout(gd.id, patch);
        }
      });
    } catch(e) {}
  }

  /* 2. UMAP LEGEND — reposition horizontal-below on mobile */
  function fixUmapLegend(gd) {
    if (!isMobile) return;
    try {
      var title = sectionTitle(gd);
      if (title.indexOf('UMAP') < 0) return;
      Plotly.relayout(gd.id, {
        'legend.orientation': 'h',
        'legend.y': -0.22,
        'legend.x': 0,
        'legend.xanchor': 'left',
        'legend.yanchor': 'top',
        'legend.font.size': 9,
        'margin.b': 90
      });
    } catch(e) {}
  }

  /* 3. CCM mobile readability — bump tick fonts, shrink margins */
  function fixCcm(gd) {
    if (!isMobile) return;
    try {
      var title = sectionTitle(gd);
      if (title.indexOf('CCM') < 0 && title.indexOf('CONVERGENT') < 0) return;
      Plotly.relayout(gd.id, {
        'margin.l': 56,
        'margin.r': 12,
        'margin.t': 40,
        'margin.b': 60,
        'xaxis.tickfont.size': 10,
        'yaxis.tickfont.size': 10,
        'xaxis.title.font.size': 11,
        'yaxis.title.font.size': 11,
        'legend.font.size': 9
      });
    } catch(e) {}
  }

  /* 4. TASTE HEATMAP — extend coverage to image/heatmapgl variants the existing observer misses */
  function fixTasteHeatmapVariants(gd) {
    if (!isMobile) return;
    try {
      var data = gd._fullData || [];
      var isVariant = data.some(function(tr){ return tr.type === 'image' || tr.type === 'heatmapgl'; });
      if (!isVariant) return;
      var title = sectionTitle(gd);
      if (title.indexOf('TASTE') < 0 && title.indexOf('HEATMAP') < 0 && title.indexOf('GATEWAY') < 0) return;
      var w = Math.max(340, window.innerWidth - 24);
      Plotly.relayout(gd.id, {
        autosize: false,
        width: w,
        'margin.l': 80,
        'margin.r': 10,
        'margin.b': 40,
        'margin.t': 30,
        'xaxis.tickfont.size': 8,
        'yaxis.tickfont.size': 8,
        'yaxis.automargin': false,
        'xaxis.automargin': false
      });
    } catch(e) {}
  }

  function processChart(gd) {
    if (!gd || !gd.id || patched.has(gd.id)) return;
    whenReady(gd, function(g) {
      patched.add(g.id);
      fixYearTicks(g);
      fixUmapLegend(g);
      fixCcm(g);
      fixTasteHeatmapVariants(g);
    });
  }

  function scanAll() {
    document.querySelectorAll('.plotly-graph-div').forEach(processChart);
  }

  if (document.readyState === 'complete') {
    setTimeout(scanAll, 700);
  } else {
    window.addEventListener('load', function(){ setTimeout(scanAll, 700); });
  }

  var st;
  window.addEventListener('scroll', function(){
    clearTimeout(st);
    st = setTimeout(scanAll, 800);
  }, { passive: true });

  var mo = new MutationObserver(function(muts){
    muts.forEach(function(m){
      m.addedNodes.forEach(function(node){
        if (node.nodeType !== 1) return;
        var divs = node.classList && node.classList.contains('plotly-graph-div')
