          : (node.querySelectorAll ? Array.from(node.querySelectorAll('.plotly-graph-div')) : []);
        divs.forEach(function(gd){ setTimeout(function(){ processChart(gd); }, 400); });
      });
    });
  });
  mo.observe(document.body, { childList: true, subtree: true });

  console.log('[audit-fix-2026-05] armed: year-ticks + UMAP-legend + CCM-mobile + taste-imshow');
})();

(function(){
  'use strict';
  /* The base tooltip JS flips LEFT when a term is near the right edge.
     It does NOT handle the left edge, so centered tooltips on left-side terms
     spilled off-screen. This adds the missing left-edge case. */
  function clampTip(el){
    try{
      var r = el.getBoundingClientRect();
      var vw = window.innerWidth;
      var tipW = Math.min(280, vw * 0.72);
      var center = r.left + r.width / 2;
      if ((vw - r.right) < 160){ el.classList.remove('tip-flip-right'); return; } /* near right → existing flip-left owns it */
      if (center - tipW / 2 < 6){ el.classList.add('tip-flip-right'); }
      else { el.classList.remove('tip-flip-right'); }
    }catch(e){}
  }
  function onEnter(e){
    var t = e.target;
    if (t && t.classList && t.classList.contains('term-tip')) clampTip(t);
  }
  document.addEventListener('mouseover', onEnter, {passive:true});
  document.addEventListener('focusin', onEnter, {passive:true});
})();

(function () {
  'use strict';
  var data = [];
  try { data = JSON.parse(document.getElementById('h1loop-data').textContent); } catch (e) {}
  if (!Array.isArray(data) || data.length < 2) return;

  var DEGS = [0, 2, 3, 5, 7, 9, 10, 12];      // D Dorian degrees (+ octave)
  function nameDegree(name) { var h = 0, s = name || ''; for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return DEGS[h % DEGS.length]; }
  function phrase() { return data.map(function (d) { return { freq: 146.83 * Math.pow(2, nameDegree(d.artist) / 12) }; }); }  // each artist → a D-Dorian note

  var running = false, loopTimer = null;
  function play() {
    if (running || !window.__sonify || !window.__sonify.motif) return;
    running = true;
    var notes = phrase(), LOOPS = 3, span = notes.length * 0.42, i = 0;
    (function once() {
      if (!running) return;
      window.__sonify.motif(notes, { step: 0.42, vol: 0.12, dur: 0.7, type: 'sine', pan: 0 });
      i++; if (i < LOOPS) loopTimer = setTimeout(once, span * 1000); else running = false;
    })();
  }
  function stop() { running = false; if (loopTimer) { clearTimeout(loopTimer); loopTimer = null; } }

  var btn = document.getElementById('h1loop-btn');
  if (btn) btn.addEventListener('click', function () { setTimeout(play, 200); }, { passive: true });
  ['h1loop-exit', 'h1l-stop'].forEach(function (id) { var b = document.getElementById(id); if (b) b.addEventListener('click', stop, { passive: true }); });

  window.__sonifyH1 = { play: play, stop: stop };
  console.log('[sonic-init] SONIFY-H1 (topological loop as audio) armed ·', data.length, 'nodes');
})();

