(function(){
  if (window.__applePolish2) return; window.__applePolish2 = true;

  // (a) GENRE FAMILIES treemap (#fig-52) renders blank: branchvalues:'total' but a
  // parent value sits ~1e-4 below its children's sum (float rounding) → Plotly
  // drops the trace. Bump any offending parent to its children's sum, then re-render.
  function fixTreemaps(){
    if (!window.Plotly) return;
    document.querySelectorAll('.js-plotly-plot').forEach(function(gd){
      if (!gd.data || !gd.data.length) return;
      gd.data.forEach(function(tr, ti){
        if ((tr.type!=='treemap' && tr.type!=='sunburst') || tr.branchvalues!=='total' || !tr.values) return;
        if (tr.__spineTreemapFixed) return;
        var ids = tr.ids || tr.labels; if (!ids) return;
        var parents = tr.parents || [], sumKids={};
        for (var i=0;i<ids.length;i++){ var p=parents[i]; if (p!=null && p!=='') sumKids[p]=(sumKids[p]||0)+(+tr.values[i]||0); }
        var nv=tr.values.slice(), changed=false;
        for (var j=0;j<ids.length;j++){
          var ks=sumKids[ids[j]]; if (ks!=null && ks>(+nv[j]||0)){ nv[j]=ks*1.0000005; changed=true; }
        }
        if (changed){
          tr.__spineTreemapFixed=true;
          // restyle with a fresh array forces a real re-render (react diffs by ref)
          try{ window.Plotly.restyle(gd, {values:[nv]}, [ti]); }catch(e){}
        }
      });
    });
  }

  // (b) NEXT-PRESS PREDICTORS (#fig-25) legend overlaps a subplot title — move it below.
  function fixLegend25(){
    if (!window.Plotly) return;
    var p=document.querySelector('#fig-25 .js-plotly-plot');
    if (p && p.layout){ try{ window.Plotly.relayout(p, {'legend.orientation':'h','legend.x':0.88,'legend.xanchor':'center','legend.y':-0.16,'legend.yanchor':'top'}); }catch(e){} }
  }

  // (c) Glossary "↩ used in:" backrefs show the same label twice (distinct figs,
  // identical link text). Collapse to unique labels so it doesn't read as a dupe.
  function dedupeBackrefs(){
    document.querySelectorAll('.back-refs').forEach(function(box){
      var seen={};
      [].slice.call(box.querySelectorAll('a')).forEach(function(a){
        var key=(a.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();
        if (!key) return;
        if (seen[key]){
          var sib=a.nextSibling;
          if (sib && sib.nodeType===3 && /^[\s,·•/|]+$/.test(sib.textContent)) sib.parentNode.removeChild(sib);
          else { var prev=a.previousSibling; if (prev && prev.nodeType===3 && /^[\s,·•/|]+$/.test(prev.textContent)) prev.parentNode.removeChild(prev); }
          a.parentNode.removeChild(a);
        } else seen[key]=1;
      });
    });
  }

  function run(){ try{fixTreemaps();}catch(e){} try{fixLegend25();}catch(e){} try{dedupeBackrefs();}catch(e){} }
  window.addEventListener('sonic:plotly-rendered', function(){ setTimeout(run, 80); });
  function schedule(){ [1500,3500,6500].forEach(function(t){ setTimeout(run,t); }); }
  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded', schedule); else schedule();
})();

