      if (/\bcyber-nav\b|\bsubmenu\b|\bact-chip\b/.test(cls)) return null;
      if (/\bfig-caption\b|\bae-caption\b|\bexo-caption\b|\bmethod-line\b|\bmethod-note\b|\bact-look\b|\bexo-intro\b|\bexo-lede\b|\bexo-note\b|\bscrolly-copy\b|\bsect-tldr\b|\babout-body\b|\babout-dash\b|\btable-panel\b/.test(cls)) return el;
      el = el.parentElement;
