  function escapeRe(s){ return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
  function makeRe(term){
    var startAlnum = /^[A-Za-z0-9]/.test(term);
    var endAlnum   = /[A-Za-z0-9]/.test(term[term.length-1]);
    var pat = escapeRe(term);
    var pre  = startAlnum ? '(?<![A-Za-z0-9_])' : '';
    var post = endAlnum   ? '(?![A-Za-z0-9_])'  : '';
