  function wrapTerms(){
    var done = {};
    TIPS.forEach(function(t){ done[t[0]] = false; });
    // capture which terms are already wrapped elsewhere on the page, to avoid duplicates
    document.querySelectorAll('.term-tip').forEach(function(s){
      var txt = (s.textContent || '').trim();
      TIPS.forEach(function(t){ if (txt === t[0]) done[t[0]] = true; });
    });

