        var cursor = 0;
        clean.forEach(function(h){
          if (h.index > cursor) frag.appendChild(document.createTextNode(t.slice(cursor, h.index)));
          var span = document.createElement('span');
          span.className = 'term-tip';
          span.setAttribute('data-tip', h.tip);
          span.setAttribute('tabindex', '0');
          span.textContent = h.text;
          frag.appendChild(span);
          cursor = h.index + h.len;
          wrapped.push(h.term);
        });
        if (cursor < t.length) frag.appendChild(document.createTextNode(t.slice(cursor)));
        rec.node.parentNode.replaceChild(frag, rec.node);
