     Normalize the inline-dot ".ae-caption" blocks and the colon-less ".exo-caption"
     pillar labels to the dominant labeled-line convention: <b class="pl-X">Label:</b> ... <br>. */
  var LABEL_CLASS = {
    'math':'pl-math', 'intuition':'pl-intuition',
    'my data':'pl-yourdata', 'mydata':'pl-yourdata', 'yourdata':'pl-yourdata',
    'takeaway':'pl-takeaway'
  };
