    var k = label.toLowerCase().replace(/\s+/g,' ').trim();
    return LABEL_CLASS[k] || LABEL_CLASS[k.replace(/\s+/g,'')] || 'pl-math';
  }

  function normalizeAeCaptions(){
    document.querySelectorAll('.ae-caption').forEach(function(cap){
      if (cap.dataset.cfNormalized === '1') return;
