      // Convert "<b style="...">Label</b> —" into a labeled-line bold marker.
      html = html.replace(/<b\s+style="[^"]*">\s*(Math|Intuition|My data|Takeaway)\s*<\/b>\s*(?:&mdash;|—|-{1,2})\s*/gi,
        function(_, label){
          return '<b class="' + plClassFor(label) + '">' + label + ':</b> ';
        });
      // Replace the " ·" inline separators that precede a labeled line with a <br>.
      html = html.replace(/\s*[··]\s*(?=<b class="pl-)/g, '<br>');
      // Tidy any stray leading/trailing separators or whitespace runs.
      html = html.replace(/^[\s··]+/, '').replace(/[\s··]+$/, '');
      html = html.replace(/\s{2,}/g, ' ');
      cap.innerHTML = html;
      cap.dataset.cfNormalized = '1';
    });
  }

  function normalizeExoCaptions(){
    document.querySelectorAll('.exo-caption .pillar').forEach(function(b){
      if (b.dataset.cfNormalized === '1') return;
      var label = (b.textContent || '').trim();
      var k = label.toLowerCase();
      if (!(k in LABEL_CLASS) && !(k.replace(/\s+/g,'') in LABEL_CLASS)) { b.dataset.cfNormalized='1'; return; }
      b.classList.add(plClassFor(label));
      if (!/:\s*$/.test(b.textContent)) b.textContent = label + ':';
      b.dataset.cfNormalized = '1';
    });
  }

  function run(){
    try{ fixSparklines(); }catch(e){}
    try{ normalizeAeCaptions(); }catch(e){}
    try{ normalizeExoCaptions(); }catch(e){}
    try{ wrapTerms(); }catch(e){}
