  if(nReason/nRaw<0.5)throw{refusal:'your export doesn’t carry the <b>reason_start</b> field (present on '+Math.round(100*nReason/nRaw)+'% of rows). older exports omit it; without it I can’t separate your picks from autoplay. nothing to send. sorry, and thanks for trying.'};
  var nPlays=tsA.length;
  if(nPlays<CFG.minPlays)throw{refusal:'only '+fmt(nPlays)+' qualified plays (≥30s with artist metadata); the probe needs '+fmt(CFG.minPlays)+' for a stable estimate. nothing to send.'};

  // chronological sort (ISO8601 Z sorts lexicographically)
  var order=new Array(nPlays);for(var i=0;i<nPlays;i++)order[i]=i;
  order.sort(function(x,y){return tsA[x]<tsA[y]?-1:tsA[x]>tsA[y]?1:0;});
  var ts2=new Array(nPlays),an2=new Array(nPlays),rs2=new Array(nPlays),sh2=new Array(nPlays);
  for(i=0;i<nPlays;i++){var o=order[i];ts2[i]=tsA[o];an2[i]=artNamesTmp[o];rs2[i]=rsA[o];sh2[i]=shA[o];}
  tsA=ts2;rsA=rs2;shA=sh2;

  // artist ids, sorted for determinism (mirrors python's sorted set)
  var uniq=Array.from(new Set(an2)).sort();
  for(i=0;i<uniq.length;i++)artMap.set(uniq[i],i);
  var nA=uniq.length;
  var aid=new Int32Array(nPlays);
  for(i=0;i<nPlays;i++)aid[i]=artMap.get(an2[i]);

  // provenance split (display): tap = deliberate; else shuffle flag = shuffle; else machine-queued
  var nDel=0,nShf=0;
  for(i=0;i<nPlays;i++){if(TAP[rsA[i]]===1)nDel++;else if(shA[i])nShf++;}
  var pctDeliberate=nDel/nPlays;
  var years=[parseInt(tsA[0].slice(0,4),10),parseInt(tsA[nPlays-1].slice(0,4),10)];

  // sessions + transitions (verbatim logic: landing track's reason_start)
  prog(fmt(nRaw)+' rows → '+fmt(nPlays)+' qualified plays · building sessions…');await tick();
  var sessions=[];var cur=[];
  var trA=[],trB=[],trI=[],trS=[];
  var prevAid=-1,prevT=0,sid=-1;
  for(i=0;i<nPlays;i++){
    var t=Date.parse(tsA[i].slice(0,19)+'Z')/1000;
    if(!isFinite(t))continue;
    var isNew=prevAid<0||(t-prevT)>CFG.gapS;
    if(isNew){if(cur.length)sessions.push(cur);cur=[];sid++;}
    else{
      var rs=rsA[i],intent=-1;
      if(TAP[rs]===1)intent=1;
      else if(rs==='trackdone'&&!shA[i])intent=0;
      if(intent>=0){trA.push(prevAid);trB.push(aid[i]);trI.push(intent);trS.push(sid);}
    }
    cur.push(aid[i]);prevAid=aid[i];prevT=t;
  }
  if(cur.length)sessions.push(cur);
  var nSessions=sessions.length,nClass=trA.length;

  // session co-occurrence graph (window 5, 1/d weights)
  prog(fmt(nSessions)+' sessions · weaving the co-occurrence graph…');await tick();
  var edges=new Map();
  for(var si=0;si<nSessions;si++){
    var seq=sessions[si],L=seq.length;
    for(i=0;i<L;i++){
      var ai=seq[i];
      for(var d=1;d<=CFG.win;d++){
        var j=i+d;if(j>=L)break;
        var bj=seq[j];if(ai===bj)continue;
        var key=ai<bj?ai*nA+bj:bj*nA+ai;
        edges.set(key,(edges.get(key)||0)+1/d);
      }
    }
    if(si%3000===2999)await tick();
  }
  var nE=edges.size;

  // adjacency (CSR)
  var deg=new Int32Array(nA);
  edges.forEach(function(w,k){var a=Math.floor(k/nA),b=k%nA;deg[a]++;deg[b]++;});
  var off=new Int32Array(nA+1);
  for(i=0;i<nA;i++)off[i+1]=off[i]+deg[i];
  var nbr=new Int32Array(off[nA]),wgt=new Float64Array(off[nA]);
  var fill=Int32Array.from(off.subarray(0,nA));
  edges.forEach(function(w,k){var a=Math.floor(k/nA),b=k%nA;nbr[fill[a]]=b;wgt[fill[a]++]=w;nbr[fill[b]]=a;wgt[fill[b]++]=w;});

  // single-pass seeded label propagation (NOT louvain; probe-grade only)
  prog(fmt(nA)+' artists · '+fmt(nE)+' edges · label propagation (seed '+CFG.seed+')…');await tick();
  var lporder=new Int32Array(nA);for(i=0;i<nA;i++)lporder[i]=i;
  shuffleArr(lporder,rng);
  var labels=new Int32Array(nA);for(i=0;i<nA;i++)labels[i]=i;
  var tally=new Map();
  for(var oi=0;oi<nA;oi++){
    i=lporder[oi];
    if(off[i+1]===off[i])continue;
    tally.clear();
    for(var e2=off[i];e2<off[i+1];e2++){
      var Lb=labels[nbr[e2]];
      tally.set(Lb,(tally.get(Lb)||0)+wgt[e2]);
    }
    var best=-1,bw=-Infinity;
    tally.forEach(function(w,Lc){if(w>bw+1e-12||(Math.abs(w-bw)<=1e-12&&Lc<best)){bw=w;best=Lc;}});
    if(best>=0)labels[i]=best;
  }
  var sizes=new Int32Array(nA);
  for(i=0;i<nA;i++)sizes[labels[i]]++;
  var nCommRaw=0,nKept=0;
  for(i=0;i<nA;i++){if(sizes[i]>0){nCommRaw++;if(sizes[i]>=CFG.minComm)nKept++;}}
  if(nKept<2)throw{refusal:'the co-occurrence graph collapsed into a single community on this log, so cross-community rates are undefined here. the python probe (louvain) may still work; nothing to send from this tab.'};
  var labVec=new Int32Array(nA);
  for(i=0;i<nA;i++)labVec[i]=sizes[labels[i]]>=CFG.minComm?labels[i]:-1;

  // modularity of the raw partition (mirrors python's full-label modularity)
  var mTot=0;var strength=new Float64Array(nA);
  var wIn=new Map(),sTot=new Map();
  edges.forEach(function(w,k){
    var a=Math.floor(k/nA),b=k%nA;
    mTot+=w;strength[a]+=w;strength[b]+=w;
    if(labels[a]===labels[b])wIn.set(labels[a],(wIn.get(labels[a])||0)+w);
  });
  for(i=0;i<nA;i++){if(strength[i]>0)sTot.set(labels[i],(sTot.get(labels[i])||0)+strength[i]);}
  var qMod=0;
  if(mTot>0)sTot.forEach(function(sV,c){qMod+=(wIn.get(c)||0)/mTot-Math.pow(sV/(2*mTot),2);});

  // observed BI over transitions with both endpoints partitioned
  prog(fmt(nKept)+' communities (≥'+CFG.minComm+' artists) · computing your bridge index…');await tick();
  var tapA=[],tapB=[],tapS=[],algA=[],algB=[],algS=[];
  for(i=0;i<nClass;i++){
    var pa=trA[i],pb=trB[i];
    if(labVec[pa]<0||labVec[pb]<0)continue;
    if(trI[i]===1){tapA.push(pa);tapB.push(pb);tapS.push(trS[i]);}
    else{algA.push(pa);algB.push(pb);algS.push(trS[i]);}
  }
  if(!tapA.length||!algA.length)throw{refusal:'no usable tap and/or autoplay transitions after partitioning. the probe can’t form the ratio on this log. nothing to send.'};
  if(tapA.length<500)warnings.push('fewer than 500 deliberate (tap) transitions; expect a wide interval');
  var nT=tapA.length,nG=algA.length;
  var tapCross=0,algCross=0;
  var tA32=Int32Array.from(tapA),tB32=Int32Array.from(tapB),gA32=Int32Array.from(algA),gB32=Int32Array.from(algB);
  for(i=0;i<nT;i++)if(labVec[tA32[i]]!==labVec[tB32[i]])tapCross++;
  for(i=0;i<nG;i++)if(labVec[gA32[i]]!==labVec[gB32[i]])algCross++;
  var tapRate=tapCross/nT,algRate=algCross/nG;
  if(algRate<=0)throw{refusal:'your autoplay cross-community rate is zero. the bridge index is undefined on this log. nothing to send.'};
  var biObs=tapRate/algRate;
  var coverage=(nT+nG)/Math.max(nClass,1);

  // mechanical floor: size-preserving label shuffles over partitioned nodes
  prog('BI '+biObs.toFixed(3)+' · mechanical floor ('+CFG.nShuf+' label shuffles)…');await tick();
  var partNodes=[];
  for(i=0;i<nA;i++)if(labVec[i]>=0)partNodes.push(i);
  var P=partNodes.length;
  var nodePos=new Int32Array(nA);for(i=0;i<nA;i++)nodePos[i]=-1;
  for(i=0;i<P;i++)nodePos[partNodes[i]]=i;
  var baseLabs=new Int32Array(P);
  for(i=0;i<P;i++)baseLabs[i]=labVec[partNodes[i]];
  var ta=new Int32Array(nT),tb=new Int32Array(nT),ga=new Int32Array(nG),gb=new Int32Array(nG);
  for(i=0;i<nT;i++){ta[i]=nodePos[tA32[i]];tb[i]=nodePos[tB32[i]];}
  for(i=0;i<nG;i++){ga[i]=nodePos[gA32[i]];gb[i]=nodePos[gB32[i]];}
  var nullBI=new Float64Array(CFG.nShuf);
  var pl=new Int32Array(P);
  var nGE=0;
  for(var sh=0;sh<CFG.nShuf;sh++){
    pl.set(baseLabs);
    for(i=P-1;i>0;i--){var jj=(rng()*(i+1))|0;var tv=pl[i];pl[i]=pl[jj];pl[jj]=tv;}
    var tc=0,ac=0;
    for(i=0;i<nT;i++)if(pl[ta[i]]!==pl[tb[i]])tc++;
    for(i=0;i<nG;i++)if(pl[ga[i]]!==pl[gb[i]])ac++;
    var tr2=tc/nT,ar2=ac/nG;
    nullBI[sh]=ar2>0?tr2/ar2:NaN;
    if(isFinite(nullBI[sh])&&nullBI[sh]>=biObs)nGE++;
    if(sh%60===59){prog('mechanical floor … '+(sh+1)+'/'+CFG.nShuf);await tick();}
  }
  var fs=0,fc=0;
  for(i=0;i<CFG.nShuf;i++)if(isFinite(nullBI[i])){fs+=nullBI[i];fc++;}
  var floorMean=fc?fs/fc:NaN;
  var floorCI=[pctile(nullBI,2.5),pctile(nullBI,97.5)];
  var pPerm=(nGE+1)/(CFG.nShuf+1);
  var nLE=0;
  for(i=0;i<CFG.nShuf;i++)if(isFinite(nullBI[i])&&nullBI[i]<=biObs)nLE++;
  var pLow=(nLE+1)/(CFG.nShuf+1);

  // 95% CI: session-block bootstrap (skipped over budget)
  var biCI=null;
  if(performance.now()-t0<CFG.ciBudgetMs){
    prog('floor '+(isFinite(floorMean)?floorMean.toFixed(3):'—')+' · session-block bootstrap ('+CFG.nBoot+' resamples)…');await tick();
    var sidMap=new Map();
    for(i=0;i<nT;i++)if(!sidMap.has(tapS[i]))sidMap.set(tapS[i],sidMap.size);
    for(i=0;i<nG;i++)if(!sidMap.has(algS[i]))sidMap.set(algS[i],sidMap.size);
    var S=sidMap.size;
    var perSess=new Float64Array(S*4);
    for(i=0;i<nT;i++){var k1=sidMap.get(tapS[i])*4;perSess[k1]++;if(labVec[tA32[i]]!==labVec[tB32[i]])perSess[k1+1]++;}
    for(i=0;i<nG;i++){var k2=sidMap.get(algS[i])*4;perSess[k2+2]++;if(labVec[gA32[i]]!==labVec[gB32[i]])perSess[k2+3]++;}
    var boot=new Float64Array(CFG.nBoot);
    for(var b2=0;b2<CFG.nBoot;b2++){
      var m0=0,m1=0,m2=0,m3=0;
      for(i=0;i<S;i++){
        var pick=((rng()*S)|0)*4;
        m0+=perSess[pick];m1+=perSess[pick+1];m2+=perSess[pick+2];m3+=perSess[pick+3];
      }
      boot[b2]=(m0>0&&m2>0&&m3>0)?(m1/m0)/(m3/m2):NaN;
      if(b2%120===119){prog('bootstrap … '+(b2+1)+'/'+CFG.nBoot);await tick();}
    }
    biCI=[pctile(boot,2.5),pctile(boot,97.5)];
  } else {
    warnings.push('bootstrap ci not run (over the in-tab time budget); the python probe computes it');
  }

  var result={
    script_version:VERSION,
    partition:'single-pass seeded label propagation, NOT the paper’s louvain; magnitudes not comparable across methods',
    params:{seed:CFG.seed,ms_played_min:CFG.msMin,session_gap_min:CFG.gapS/60,cooc_window:CFG.win,min_community_size:CFG.minComm,n_shuffles:CFG.nShuf,n_boot:biCI?CFG.nBoot:0},
    n_plays:nPlays,
    n_sessions:nSessions,
    n_artists_rounded:Math.round(nA/100)*100,
    date_range_years:years,
    pct_deliberate:r4(pctDeliberate),
    n_tap_transitions:nT,
    n_algo_transitions:nG,
    tap_cross_rate:r4(tapRate),
    algo_cross_rate:r4(algRate),
    BI:r4(biObs),
    BI_CI95:biCI?[r4(biCI[0]),r4(biCI[1])]:null,
    floor_mean:r4(floorMean),
    floor_CI95:[r4(floorCI[0]),r4(floorCI[1])],
    p_perm:Math.round(pPerm*1e6)/1e6,
    partition_stats:{n_communities:nKept,n_communities_raw:nCommRaw,modularity:r4(qMod),pct_transitions_covered:r4(coverage)},
    warnings:warnings
  };
  result.__display={nDel:nDel,nShf:nShf,pLow:pLow,elapsedMs:Math.round(performance.now()-t0)};
  return result;
}

function render(res){
  var disp=res.__display;
  var box=el('fst-results'),p=el('fst-progress'),d=el('fst-drop');
  if(!box)return;
  var share={};
  for(var k in res)if(k!=='__display')share[k]=res[k];
  var json=JSON.stringify(share,null,2);
  var n=res.n_plays;
  var pd=Math.round(100*disp.nDel/n),ps=Math.round(100*disp.nShf/n),pm=100-pd-ps;
  var yrs=res.date_range_years[0]===res.date_range_years[1]?String(res.date_range_years[0]):res.date_range_years[0]+'–'+res.date_range_years[1];
  var ratio=res.BI/res.floor_mean;
  var verdict,hit=false;
  if(res.p_perm<0.05&&res.BI>res.floor_mean){verdict='you bridge '+ratio.toFixed(2)+'× your mechanical floor.';hit=true;}
  else if(disp.pLow<0.05&&res.BI<res.floor_mean){verdict='inverse asymmetry: your autoplay crosses your communities more than your taps do.';}
  else{verdict='no detectable asymmetry above your mechanical floor.';}
  var ciLine=res.BI_CI95?('95% ci ['+res.BI_CI95[0].toFixed(2)+', '+res.BI_CI95[1].toFixed(2)+'] (session-block bootstrap, '+res.params.n_boot+' resamples)'):'ci not run (time budget); the python probe computes it';
  var mail='mailto:astralcrestlab@proton.me?subject='+encodeURIComponent('bridge probe result (in-tab self-test)')+'&body='+encodeURIComponent(json+'\n\n(sent from the sonicManifold in-tab probe: aggregates only, no names, no timestamps.)');
  var html=''
   +'<div class="fst-grid">'
   +'<div class="fst-stat"><span class="fst-n">'+fmt(n)+'</span><span class="fst-l">qualified plays</span></div>'
   +'<div class="fst-stat"><span class="fst-n">'+yrs+'</span><span class="fst-l">years</span></div>'
   +'<div class="fst-stat"><span class="fst-n">'+fmt(res.n_sessions)+'</span><span class="fst-l">sessions</span></div>'
   +'<div class="fst-stat"><span class="fst-n">~'+fmt(res.n_artists_rounded)+'</span><span class="fst-l">artists</span></div>'
   +'</div>'
   +'<div class="fst-bar"><i class="b-del" style="width:'+pd+'%"></i><i class="b-shf" style="width:'+ps+'%"></i><i class="b-mch" style="width:'+pm+'%"></i></div>'
   +'<div class="fst-split">'
   +'<div class="fst-seg del"><span class="n">'+pd+'%</span><span class="l">deliberate</span></div>'
   +'<div class="fst-seg shf"><span class="n">'+ps+'%</span><span class="l">shuffle</span></div>'
   +'<div class="fst-seg mch"><span class="n">'+pm+'%</span><span class="l">machine-queued</span></div>'
   +'</div>'
   +'<div class="fst-verdict'+(hit?' hit':'')+'">'+verdict+'</div>'
   +'<p class="fst-probeline">bridge index '+res.BI.toFixed(3)+' · tap cross-rate '+res.tap_cross_rate.toFixed(3)+' vs autoplay '+res.algo_cross_rate.toFixed(3)+' · floor '+res.floor_mean.toFixed(3)+' ['+res.floor_CI95[0].toFixed(2)+', '+res.floor_CI95[1].toFixed(2)+'] · p='+res.p_perm.toFixed(4)+' · '+ciLine+' · '+fmt(res.partition_stats.n_communities)+' communities · '+disp.elapsedMs+'ms, all in this tab</p>'
   +(res.warnings.length?'<p class="fst-warnline">'+res.warnings.join(' · ')+'</p>':'')
   +'<p class="fst-caveat">honesty note: this in-tab probe partitions your artist graph with single-pass label propagation, not the paper’s louvain. the magnitude is not comparable to the study’s number (or anyone else’s). for the paper-grade number, run the python probe (<a href="probe/bridge_probe.py" download>bridge_probe.py</a> · <a href="probe/BRIDGE_PROBE_INSTRUCTIONS.md" target="_blank" rel="noopener">instructions</a>) on the same folder. the ratio-vs-your-own-floor above is the honest read.</p>'
   +'<div class="fst-share">'
   +'<button class="fst-btn" id="fst-copy" type="button">copy aggregates</button>'
   +'<a class="fst-btn" id="fst-mail" href="'+mail+'">email it → astralcrestlab@proton.me</a>'
   +'</div>'
   +'<p class="fst-ask">if you send this, you become n=2. that’s the whole ask.</p>'
   +'<details class="fst-json"><summary>the exact json: everything that would leave, and nothing else</summary><pre id="fst-pre"></pre></details>'
   +'<button class="fst-reset" id="fst-reset" type="button">run another export</button>';
  box.innerHTML=html;
  el('fst-pre').textContent=json;
  box.hidden=false;
  if(p)p.hidden=true;
  if(d)d.hidden=true;
  el('fst-reset').addEventListener('click',resetUI);
  el('fst-copy').addEventListener('click',function(){
    var btn=this;
    function done(ok){btn.textContent=ok?'copied.':'copy failed. use the json below';setTimeout(function(){btn.textContent='copy aggregates';},1800);}
    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(json).then(function(){done(true);},function(){done(false);});}
    else{try{var ta2=document.createElement('textarea');ta2.value=json;document.body.appendChild(ta2);ta2.select();document.execCommand('copy');document.body.removeChild(ta2);done(true);}catch(e){done(false);}}
  });
  window.__fstLast=share;
}

var busy=false;
function handleFiles(fileList){
  if(busy||!fileList||!fileList.length)return;
  var files=Array.prototype.slice.call(fileList); // snapshot BEFORE resetUI clears the live FileList
  busy=true;
  resetUI();
  var d=el('fst-drop');if(d)d.hidden=true;
  compute(files).then(function(res){busy=false;render(res);})
  .catch(function(err){
    busy=false;
    var d2=el('fst-drop');if(d2)d2.hidden=false;
    if(err&&err.refusal)refuse(err.refusal);
    else{refuse('something broke while computing ('+((err&&err.message)||err)+'). nothing was sent anywhere. it never is.');}
  });
}

