function wire(){
  var input=el('fst-file'),drop=el('fst-drop');
  if(!input||!drop)return;
  input.addEventListener('change',function(){handleFiles(input.files);});
  ['dragenter','dragover'].forEach(function(ev){
    drop.addEventListener(ev,function(e){e.preventDefault();e.stopPropagation();drop.classList.add('drag');});
  });
  ['dragleave','dragend'].forEach(function(ev){
    drop.addEventListener(ev,function(e){e.preventDefault();drop.classList.remove('drag');});
  });
  drop.addEventListener('drop',function(e){
    e.preventDefault();e.stopPropagation();drop.classList.remove('drag');
    if(e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files.length)handleFiles(e.dataTransfer.files);
  });
}
function mount(){
  if(el('fable-selftest'))return true;
  var anchor=el('gauntlet')||el('apple-leadhero')||el('act-1');
  if(!anchor||!anchor.parentNode)return false;
  var sec=document.createElement('section');
  sec.id='fable-selftest';
  sec.setAttribute('aria-label','run the bridge probe on your own spotify export: in this tab, nothing uploads');
  sec.innerHTML=TPL;
  anchor.insertAdjacentElement('afterend',sec);
  wire();
  return true;
}
